/* ---------- drawing helpers for this lesson (prefixed VL_ so they never clash with engine globals) ---------- */
const VL_F='font-family="Nunito Sans, sans-serif"';
const VL_T=(x,y,t,o={})=>`<text x="${x}" y="${y}" ${VL_F} font-size="${o.fs||24}" font-weight="${o.fw||600}" text-anchor="${o.a||'start'}" fill="${o.fill||'#18213A'}">${t}</text>`;
const VL_L=(x1,y1,x2,y2,col='#5C6577',w=2,ex='')=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${col}" stroke-width="${w}" stroke-linecap="round" ${ex}/>`;
const VL_box=(x,y,w,h,o={})=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${o.r??14}" fill="${o.fill||'#FFFFFF'}" stroke="${o.st||'#CED4DA'}" stroke-width="${o.sw||2}" ${o.ex||''}/>`;
const VL_cell=(x,y,w,h,t,o={})=>VL_box(x,y,w,h,{r:o.r??8,fill:o.fill,st:o.st,sw:o.sw,ex:o.ex})+VL_T(x+w/2,(y+h/2+(o.fs||24)*.36).toFixed(1),t,{fs:o.fs||24,fw:o.fw||800,a:'middle',fill:o.tc||'#18213A'});
const VL_arrow=(x1,y1,x2,y2,col='#18213A',w=3)=>{const a=Math.atan2(y2-y1,x2-x1),h=14;return VL_L(x1,y1,(x2-h*.6*Math.cos(a)).toFixed(1),(y2-h*.6*Math.sin(a)).toFixed(1),col,w)+`<polygon points="${x2},${y2} ${(x2-h*Math.cos(a)+h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)-h*.5*Math.cos(a)).toFixed(1)} ${(x2-h*Math.cos(a)-h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)+h*.5*Math.cos(a)).toFixed(1)}" fill="${col}"/>`};
const VL_poly=(pts,col,w=3,ex='')=>`<polyline points="${pts.map(p=>p[0].toFixed(1)+','+p[1].toFixed(1)).join(' ')}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linejoin="round" stroke-linecap="round" ${ex}/>`;
const VL_X=(x,y,s,col,w=5)=>VL_L(x-s,y-s,x+s,y+s,col,w)+VL_L(x-s,y+s,x+s,y-s,col,w);
const VL_band=(y,h,t)=>VL_box(14,y,612,h)+VL_T(34,y+32,t,{fs:22,fw:800});
const VL_GR='#5C6577';
