const VL_MARCH=[['⇕(w0)',1],['⇑(r0, w1)',2],['⇑(r1, w0)',2],['⇓(r0, w1)',2],['⇓(r1, w0)',2],['⇕(r0)',1]];
/* worked example 2, simulated: 4 cells, up-inversion coupling fault, cell 2 rising flips cell 0 */
const VL_DRY=(()=>{let m=[0,0,0,0];const R=[{lab:'⇕(w0)',m:[...m],hl:-1}];
 for(let a=0;a<4;a++){const old=m[a];m[a]=1;let fl=-1;if(a===2&&old===0){m[0]^=1;fl=0}R.push({lab:`⇑(r0, w1) @${a}`,m:[...m],hl:a,fl})}
 R.push({lab:'⇑(r1, w0) @0',m:[...m],hl:0,fail:m[0]!==1});return R})();
/* ADC example: widths in mV around codes 63..66, 1 LSB = 10 mV */
const VL_LSB=2.56/256*1000;                                 // 10 mV
const VL_W=[10,14,6,10], VL_DNL=VL_W.map(w=>w/VL_LSB-1);    // 0, +0.4, -0.4, 0
const VL_INL=VL_DNL.reduce((a,d)=>{a.push((a.length?a[a.length-1]:0)+d);return a},[]);   // 0, 0.4, 0, 0
