const VL_MW=[10,20,0,10], VL_MD=VL_MW.map(w=>w/10-1), VL_MI=VL_MD.reduce((a,d)=>{a.push((a.length?a[a.length-1]:0)+d);return a},[]);  // DNL 0,+1,-1,0; INL 0,1,0,0
